create type public.content_status as enum ('draft','published','archived');
create table public.courses (id uuid primary key default gen_random_uuid(), course_key text unique not null, title text not null, created_at timestamptz not null default now());
create table public.stages (id uuid primary key default gen_random_uuid(), course_id uuid not null references public.courses(id), stage_key text not null, title text not null, position integer not null, unique(course_id,stage_key));
create table public.content_versions (id uuid primary key default gen_random_uuid(), stage_id uuid not null references public.stages(id), status public.content_status not null default 'draft', version_number integer not null, source_hash text not null, parser_version text not null, source_file_set jsonb not null default '[]', content_json jsonb not null, created_at timestamptz not null default now(), unique(stage_id,source_hash,parser_version));
create table public.content_import_jobs (id uuid primary key default gen_random_uuid(), repository text, commit_sha text, workflow_run_id text, workflow_run_url text, mode text not null check(mode='draft'), status text not null, manifest_json jsonb not null, warning_count integer not null default 0, error_count integer not null default 0, started_at timestamptz not null default now(), completed_at timestamptz);
create table public.answers (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), question_key text not null, content_version_id uuid not null references public.content_versions(id), value jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,question_key,content_version_id));
create table public.progress (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), stage_id uuid not null references public.stages(id), last_step_key text, last_question_key text, updated_at timestamptz not null default now(), unique(user_id,stage_id));
alter table public.answers enable row level security; alter table public.progress enable row level security;
create policy "students manage own answers" on public.answers for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "students manage own progress" on public.progress for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
